const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Step 4: AI call";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
// The webhook's field, as the rule reads it in n8n: $('Step 1: Lead assigned').first().json.body.
DATA["Step 1: Lead assigned"] = [{ json: { body: { lead_id: input.t_lead_id } } }];
const BODIES = (out) => ({"note_body": JSON.stringify({ lead_id: $('Step 3: Read the lead').first().json.id, title: out.title, check: out.check, text: out.text, sources: out.sources }), "done_body": JSON.stringify({ status: 'done', result: out.check }), "log_body": JSON.stringify({ recipe: 'R5.2', item: $('Step 1: Lead assigned').first().json.body.lead_id, decision: 'brief ' + out.check, rules: { check: out.check, problems: out.problems, criteria: out.criteria_counts, sources: out.sources.map(s => s.id + (s.status === 'not fetched' ? ' (not fetched)' : '')) } }), "failed_body": JSON.stringify({ recipe: 'R5.2', item: $('Step 1: Lead assigned').first().json.body.lead_id, reason: 'write failed', detail: 'Brief note write failed, not retried; attach it by hand or release the key', owner: $('Config').first().json.brief_owner })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
